// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge as C} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzing the caller address and an amount that may be incorrect
    function testFuzz_property(address caller, uint256 sendAmount) public {
        caller = address(uint160(bound(uint256(uint160(caller)), 0xffff + 1, type(uint160).max)));
        vm.assume(caller.code.length == 0 && caller != address(this) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        // keep caller non-zero and not the test contract itself to simulate external EOA
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // bound the sendAmount to a reasonably wide domain (0 .. 2 ether)
        uint256 amount = bound(sendAmount, 0, 2 ether);

        // prepare caller with funds
        vm.deal(caller, 5 ether);

        // ensure guesses[caller].block starts as 0 by reading via try/catch pattern when settling would revert
        // We drive lockInGuess and then inspect behavior by attempting to call settle: in the reference,
        // if lockInGuess reverted or didn't set the guess (because wrong payment), guesses[caller].block remains 0
        // and calling settle will revert due to require(guesses[msg.sender].block != 0). We capture success boolean.

        bool ok;
        vm.prank(caller);
        try c.lockInGuess{value: amount}(keccak256(abi.encodePacked("x"))) {
            ok = true;
        } catch {
            ok = false;
        }

        // After calling lockInGuess with possibly-wrong amount, attempt to call settle from the same caller.
        // In the correct contract, when msg.value != 1 ether the call must have reverted (or not set state),
        // so settle will revert because guesses[caller].block == 0. Therefore settle should revert (we treat that as okSettle==false).
        bool okSettle;
        vm.prank(caller);
        try c.settle() {
            okSettle = true;
        } catch {
            okSettle = false;
        }

        // The universal property we assert: if the payment was NOT exactly 1 ether then the reference contract
        // always ensures no state is set and thus settle will revert (okSettle == false). The mutant may allow
        // state to be set even with wrong payment, so for some fuzz input (caller, amount != 1 ether) okSettle will be true.
        // We assert that whenever the sent amount != 1 ether, settle does NOT succeed (reference satisfies this for all inputs).
        assertTrue((amount != 1 ether) ? (okSettle == false) : true);
    }
}
